from pathlib import Path
from typing import Final

import pytest

NOTES_DIR: Final = Path("notes")


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in ``names`` readable inside NOTES_DIR.

    Each name is resolved relative to NOTES_DIR. Names that are missing,
    unreadable, directories, or that resolve to a location outside NOTES_DIR
    (via ``..``, absolute paths, or symlinks) are skipped. Returns "" when
    no name yields a readable file.
    """
    base = NOTES_DIR.resolve()
    for name in names:
        try:
            target = (base / name).resolve()
            if target == base or not target.is_relative_to(base):
                continue
            return target.read_text(encoding="utf-8")
        except (OSError, ValueError):
            continue
    return ""


def _write(base: Path, rel: str, text: str) -> None:
    path = base / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    (tmp_path / "notes").mkdir()
    _write(tmp_path, "secret.txt", "SECRET")
    return tmp_path


def test_returns_first_readable_in_order(workdir: Path) -> None:
    _write(workdir, "notes/b.txt", "B")
    _write(workdir, "notes/c.txt", "C")
    assert first_readable(["missing.txt", "b.txt", "c.txt"]) == "B"


def test_empty_when_none_readable(workdir: Path) -> None:
    assert first_readable([]) == ""
    assert first_readable(["nope.txt"]) == ""


def test_directory_is_skipped(workdir: Path) -> None:
    (workdir / "notes" / "sub").mkdir()
    _write(workdir, "notes/a.txt", "A")
    assert first_readable(["sub", "a.txt"]) == "A"


def test_traversal_is_blocked(workdir: Path) -> None:
    names = [
        "../secret.txt",
        "../../secret.txt",
        "sub/../../secret.txt",
        "./../secret.txt",
        "..\\secret.txt",
    ]
    for name in names:
        assert first_readable([name]) == "", name


def test_absolute_path_is_blocked(workdir: Path) -> None:
    absolute = str((workdir / "secret.txt").resolve())
    assert first_readable([absolute]) == ""


def test_absolute_path_skipped_for_later_valid_name(workdir: Path) -> None:
    absolute = str((workdir / "secret.txt").resolve())
    _write(workdir, "notes/ok.txt", "OK")
    assert first_readable([absolute, "ok.txt"]) == "OK"


def test_symlink_escape_is_blocked(workdir: Path) -> None:
    (workdir / "notes" / "link.txt").symlink_to(workdir / "secret.txt")
    assert first_readable(["link.txt"]) == ""


def test_odd_names_do_not_crash(workdir: Path) -> None:
    for name in ["", ".", "..", "a\x00b"]:
        assert first_readable([name]) == "", repr(name)
